108	  public function checkAccess(RouteMatchInterface $route_match, AccountInterface $account) {
109	    /** @var \Drupal\commerce_order\Entity\OrderInterface $order */
110	    $order = $route_match->getParameter('commerce_order');
111	    if ($order->getState()->getId() == 'canceled') {
112	      return AccessResult::forbidden()->addCacheableDependency($order);
113	    }
114	
115	    // The user can checkout only their own non-empty orders.
116	    if ($account->isAuthenticated()) {
117	      $customer_check = $account->id() == $order->getCustomerId();
118	    }
119	    else {
120	      $active_cart = $this->cartSession->hasCartId($order->id(), CartSession::ACTIVE);
121	      $completed_cart = $this->cartSession->hasCartId($order->id(), CartSession::COMPLETED);
122	      $customer_check = $active_cart || $completed_cart;
123	    }
124	
125	    $access = AccessResult::allowedIf($customer_check)
126	      ->andIf(AccessResult::allowedIf($order->hasItems()))
127	      ->andIf(AccessResult::allowedIfHasPermission($account, 'access checkout'))
128	      ->addCacheableDependency($order);
129	
130	    return $access;
131	  }
